/**
 * Single source of truth for the YapYap accent ramp.
 *
 * Discord's blurple family is replaced by Yap pink (#FF4A74). Hover/active are
 * the same ~0.78x / ~0.67x darkening steps Discord applies to blurple; the
 * light text tones keep Discord's lightness steps on the pink hue. Every
 * palette ([YapDarkColors], future light/high-contrast themes) references
 * these — a rebrand or a new theme touches this object, not every palette.
 */
object YapAccent {
    val pink = Color(0xFFFF4A74)
    val pinkHover = Color(0xFFC73A5A)
    val pinkActive = Color(0xFFAB324E)
    val pinkSubtle = Color(0xFFFF8AA5)
    val text = Color(0xFFFF94AD)
    val link = Color(0xFFFF6D8F)
    val focus = Color(0xFFFF5F84)
    val mentionBg = Color(0x3DFF4A74) // pink @ 24 %, like Discord's mention wash
    val mentionFg = Color(0xFFFFCDD9)

    // Deep tones for accent text on light surfaces (white-on-pink contrast does
    // not transfer to pink-on-white — these hold ≥4.5:1 on white).
    val textOnLight = Color(0xFFE11D5A)
    val linkOnLight = Color(0xFFC9184A)
    val mentionFgOnLight = Color(0xFFA81244)
}

/**
 * Totally theme-independent greys shared by every palette (hover washes,
 * borders, scrims). Accent lives in [YapAccent]; add a new theme by copying
 * [YapDarkColors] and swapping the surface/text block below.
 */
private object YapNeutrals {
    val modSubtle = Color(0x1F97979F)
